/* boot_spi.S -- boot ROM of the v2 hard macro (fetch 0x000 - 0x07F,
 * example/subsystem/fc32e1s_nano_sram2k_v2_bootrom.sv, generated by build_bootrom.sh).
 *
 * RV32E on fc32e1s_nano's 6 registers (x0, ra, sp, a0..a2), no C extension.
 * MCU data address map (12 bits): SRAM 0x000 - 0x7FF, sysctl 0x800, UART 0x900,
 * SPI flash 0xA00, I2C 0xB00. 0xA00 is reached as 0xFFFFFA00 (-0x600) off x0: the upper
 * address bits do not leave the macro.
 *   1. wait for the flash's power-up time (tPU / tVSL): 10923 loops of 2 instructions at
 *      3 cycles each = 65.5k cycles, 1.8 ms at 36 MHz, longer at slower clocks; parts
 *      needing more than that need a longer reset on the board
 *   2. spi_lite_core (qspi_core's registers): ADR = 0, MAR = 0, BAR = 511 (512 words), then
 *      CCR = READ 03h, x1, memory mode, SCK divider P = 3 (SCK = clk / 4, 9 MHz at 36 MHz):
 *      flash 0x000 - 0x7FF -> SRAM 0x000 - 0x7FF
 *   3. wait until STA.busy = 0 (it covers the memory master: the last word is in the SRAM)
 *   4. jump to 0x080: the program
 * The pads are on function A (SPI) from reset. A flash image is the memory image: bytes
 * 0x000 - 0x07F are loaded too (data the program may use; fetch there sees this ROM).
 */
#define SPI       (-0x600)          /* 0xA00 */
#define SPI_CCR   (SPI + 0x00)
#define SPI_ADR   (SPI + 0x04)
#define SPI_STA   (SPI + 0x0C)
#define SPI_BAR   (SPI + 0x14)
#define SPI_MAR   (SPI + 0x18)
/* CCR: P = 3 << 25 | memory mode (24) | x1 | READ 03h */
#define CCR_BOOT  ((3 << 25) | (1 << 24) | 0x03)
#define WAIT_LOOPS 10923

    .section .text
    .globl _start
_start:
    li    a1, WAIT_LOOPS
1:  addi  a1, a1, -1
    bnez  a1, 1b
    sw    zero, SPI_ADR(zero)
    sw    zero, SPI_MAR(zero)
    li    a1, 511
    sw    a1, SPI_BAR(zero)
    li    a1, CCR_BOOT
    sw    a1, SPI_CCR(zero)
2:  lw    a1, SPI_STA(zero)
    andi  a1, a1, 2
    bnez  a1, 2b
    j     0x80
